function route(){ const q=new URLSearchParams(location.search); const r=q.get('r'); if(r){ if(q.get('k')) openAdminPage(r,q.get('k')); else if(q.get('my')) openMyPage(r,q.get('my')); else openRoomPage(r,q.get('cfg')); return; } const h=(location.hash||'#home').slice(1); if(h.startsWith('got=')){ receiveShared(h.slice(4)); return; } if(h==='create'){ if(C.step===4){ C.step=2; C.out=null; C.custom=null; delete $('#fGoal').dataset.touched; $('#fTitle').value=''; } renderCreate(); showView('create'); } else if(h==='rooms'){ renderRooms(); showView('rooms'); } else if(h==='depts'){ showView('depts'); } else if(h==='help'){ showView('help'); } else if(h==='check'){ showView('check'); } else showView('home'); }
window.addEventListener('hashchange',()=>{ if(!new URLSearchParams(location.search).get('r')) route(); });
$$('#mainNav a, #logoLink').forEach(a=>a.addEventListener('click',()=>{ if(new URLSearchParams(location.search).get('r')){ location.href=location.href.split('?')[0]+a.getAttribute('href'); return; } if(location.hash===a.getAttribute('href')) setTimeout(route,0); }));
