window.__movecoach={ S, C, MOVEMENTS, SCENES, Anim, makeAnalyzer, buildComment, buildReply, startSession, showView, api, MP, T, CK, getR:()=>R, getK:()=>K, ensureLandmarker, detectServer, squatScript, pressScript, bowScript, runScript, poseScript, archeryPose, standPose, armsPose, pressPose, buildPoseTemplate, matchMovement, poseSample, buildMotionTemplate, motionMovement, motionFrame, renderCreate, lerpPose, CHARS, Guide, getM:()=>M, getVM:()=>VM, activeRange, splitCycles, cleanShared, resultLink, DEMO_ID, DEMO_GAME_ID, useFakeLandmarker:(gen)=>{ S.landmarker={detectForVideo:(v,ts)=>({landmarks:gen(ts)}),close(){}}; S.numPoses=99; S.fake=true; }, getA:()=>A, getG:()=>G };
